// Por agencia: las etapas del pipeline y las oportunidades más recientes (12 páginas de 100: alcanza para todo el mes anterior)
const AG = { independencia: '2O4BBoTVOs95TgWbel6e', centro: 'oC2FNTV3Dc5yhLyrGvoy', periodismo: 'Jf5jBydZMO0fdMeo1d4O', matriz: 'UIJiu5Wa9iPVzMpbaZcx', hijar: '4xUuPucjdj14sqVme6sO', saltillo: 'KZbCbxCL6PH5AVNNgLQ6' };
const out = [];
for (const [agencia, loc] of Object.entries(AG)) {
  out.push({ json: { agencia, method: 'GET', path: `/opportunities/pipelines?locationId=${loc}`, ctx: { tipo: 'pipes' } } });
  for (let page = 1; page <= 12; page++)
    out.push({ json: { agencia, method: 'GET', path: `/opportunities/search?location_id=${loc}&limit=100&page=${page}&order=added_desc`, ctx: { tipo: 'opps', page } } });
}
return out;

// Reporte diario interno: últimos 7 días de cada agencia comparados con la media semanal del mes anterior
const NOMBRES = { independencia: 'Independencia', centro: 'Centro', periodismo: 'Periodismo', matriz: 'Matriz', hijar: 'Hijar', saltillo: 'Saltillo' };
const DIA = 864e5, ahora = Date.now();
const hoyMx = $now.setZone('America/Mexico_City');
const iniMesAnt = hoyMx.startOf('month').minus({ months: 1 }), finMesAnt = hoyMx.startOf('month');
const iniAyer = hoyMx.startOf('day').minus({ days: 1 }).toMillis(), finAyer = hoyMx.startOf('day').toMillis();
const etapas = {}, opps = {};
for (const it of $('GHL por agencia').all()) {
  const { agencia, ctx, res } = it.json;
  if (ctx.tipo === 'pipes') { etapas[agencia] = {}; for (const p of res.pipelines || []) for (const s of p.stages || []) etapas[agencia][s.id] = s.name; }
  else opps[agencia] = (opps[agencia] || []).concat(res.opportunities || []);
}
const grupo = (n) => /anticipo|pagado|mañana sale|en destino|de regreso|ganado/i.test(n) ? 'ventas' : /datos completos|cotizaci/i.test(n) ? 'cotizacion'
  : /[uú]ltima oportunidad|perdido/i.test(n) ? 'perdidos' : /sin ia/i.test(n) ? 'sinIA' : 'conversando';
const resumen = (lista, ag) => { const g = { total: lista.length, ventas: 0, cotizacion: 0, perdidos: 0, sinIA: 0, conversando: 0 };
  for (const o of lista) g[grupo((etapas[ag] || {})[o.pipelineStageId] || '')]++; g.avance = g.cotizacion + g.ventas; return g; };
const filas = [];
for (const ag of Object.keys(NOMBRES)) {
  const vistos = new Set();
  const lista = (opps[ag] || []).filter(o => !vistos.has(o.id) && vistos.add(o.id) && !/^prueba (ia|diaria)/i.test(o.name || ''));
  const t = (o) => new Date(o.createdAt).getTime();
  const sem = resumen(lista.filter(o => ahora - t(o) <= 7 * DIA), ag);
  // Mes anterior sin los días anormales (importaciones masivas: más del triple de la mediana diaria)
  const diaDe = (o) => new Date(t(o)).toLocaleDateString('en-CA', { timeZone: 'America/Mexico_City' });
  const delMes = lista.filter(o => t(o) >= iniMesAnt.toMillis() && t(o) < finMesAnt.toMillis());
  const porDia = {}; for (const o of delMes) porDia[diaDe(o)] = (porDia[diaDe(o)] || 0) + 1;
  const cuentas = Object.values(porDia).sort((a, b) => a - b), mediana = cuentas.length ? cuentas[Math.floor(cuentas.length / 2)] : 0;
  const raros = Object.keys(porDia).filter(d => mediana && porDia[d] > mediana * 3);
  const mes = resumen(delMes.filter(o => !raros.includes(diaDe(o))), ag);
  const ayer = lista.filter(o => t(o) >= iniAyer && t(o) < finAyer).length;
  // Si la agencia empezó a mitad del mes anterior, la media se calcula solo con los días que tienen datos
  const masVieja = lista.length ? Math.min(...lista.map(t)) : ahora;
  const desde = Math.max(iniMesAnt.toMillis(), $now.constructor.fromMillis(masVieja).setZone('America/Mexico_City').startOf('day').toMillis());
  const dias = Math.max(0, (finMesAnt.toMillis() - desde) / DIA - raros.length);
  const mesCompleto = masVieja <= iniMesAnt.toMillis() + DIA;
  filas.push({ ag, nombre: NOMBRES[ag], sem, mes, ayer, raros, mediaSem: dias >= 3 ? mes.total * 7 / dias : 0, mediaDia: dias >= 3 ? mes.total / dias : 0, mesCompleto,
    desdeTxt: mesCompleto ? '' : (dias >= 3 ? `desde el ${new Date(desde).toLocaleDateString('es-MX', { day: 'numeric', month: 'short', timeZone: 'America/Mexico_City' })}` : 'sin datos') });
}

// Rescates automáticos del último día (de ayer a las 8:00 a hoy a las 8:00)
const finR = hoyMx.startOf('day').plus({ hours: 8 }).toMillis(), iniR = finR - DIA;
// Horario de los rescates: hasta el 13 oct 11:10 h eran a las 9, 12, 15, 18 y 21 h; luego cada 30 min de 10 a 20 h y a las 0, 4 y 8 h;
// desde el 26 oct 10:07 h, cada 30 min todo el día (de noche solo rescatan a quien está escribiendo en ese momento)
const CAMBIO = Date.parse('2026-10-13T17:10:00Z'), CAMBIO2 = Date.parse('2026-10-26T16:07:00Z');
const esVuelta = (ms) => { const d = $now.constructor.fromMillis(ms).setZone('America/Mexico_City'); const h = d.hour, m = d.minute;
  if (ms < CAMBIO) return m === 0 && [9, 12, 15, 18, 21].includes(h);
  if (ms >= CAMBIO2) return true;
  return (h >= 10 && h < 20) || (h === 20 && m === 0) || (m === 0 && [0, 4, 8].includes(h)); };
let esperadas = 0; for (let t = iniR; t < finR; t += 30 * 60e3) if (esVuelta(t)) esperadas++;
const resc = {};
for (const it of $('Rescates (n8n)').all()) {
  const ag = $('Pedir rescates').all()[it.pairedItem?.item ?? 0]?.json?.agencia;
  const r = { vueltas: 0, errores: 0, revisados: 0, rescatados: 0, omitidos: 0, fallidos: 0, apiError: !Array.isArray(it.json.data) };
  for (const e of it.json.data || []) {
    const t = new Date(e.startedAt).getTime(); if (t < iniR || t >= finR) continue;
    r.vueltas++; if (e.status === 'error' || e.status === 'crashed') r.errores++;
    const rd = e.data?.resultData?.runData || {};
    r.revisados += (rd['Candidatos']?.[0]?.data?.main?.[0] || []).length;
    for (const x of rd['¿Rescatar?'] || []) for (const i of x.data?.main?.[0] || []) if (!i.json.rescatar) r.omitidos++;
    const envio = Object.keys(rd).find(k => k.startsWith('Enviar al agente'));
    for (const x of (envio ? rd[envio] : [])) for (const i of x.data?.main?.[0] || []) { if (i.json.error || x.error) r.fallidos++; else r.rescatados++; }
  }
  resc[ag] = r;
}
const hoyPr = $('Pruebas de hoy').all().map(i => i.json).filter(p => p && p.agencia);
const pct = (a, b) => b ? Math.round(a * 100 / b) : null;
const col = (v, ref, inv) => { if (ref === null || ref === undefined || !ref) return '#222'; const d = (v - ref) / ref; const malo = inv ? d > 0.15 : d < -0.15; const bueno = inv ? d < -0.15 : d > 0.15; return malo ? '#cf222e' : bueno ? '#1a7f37' : '#222'; };
const delta = (v, ref) => !ref ? '' : ` <span style="font-size:12px;color:${col(v, ref)}">(${v >= ref ? '+' : ''}${Math.round((v - ref) * 100 / ref)} %)</span>`;
const avisos = [];
const td = 'style="padding:6px 10px;border-bottom:1px solid #e5e5e5;text-align:right"', tdl = 'style="padding:6px 10px;border-bottom:1px solid #e5e5e5;text-align:left"';
const th = 'style="padding:6px 10px;background:#f3f4f6;text-align:right;font-weight:600"', thl = 'style="padding:6px 10px;background:#f3f4f6;text-align:left;font-weight:600"';
let tabla = `<table style="border-collapse:collapse;width:100%;font-size:14px"><tr><th ${thl}>Agencia</th><th ${th}>Leads 7 días</th><th ${th}>Media semanal ${iniMesAnt.setLocale('es').toFormat('LLLL')}</th><th ${th}>Ayer</th><th ${th}>% a cotización</th><th ${th}>% ${iniMesAnt.setLocale('es').toFormat('LLL')}</th><th ${th}>Perdidos</th><th ${th}>Sin IA</th><th ${th}>Prueba de hoy</th></tr>`;
for (const f of filas) {
  const p = pct(f.sem.avance, f.sem.total), pm = pct(f.mes.avance, f.mes.total);
  const pr = hoyPr.find(x => x.agencia === f.ag);
  const prTxt = !pr ? '<span style="color:#9a6700">sin prueba</span>' : pr.ok ? '✅' : `❌ ${pr.paso || ''}`;
  if (pr && !pr.ok) avisos.push(`${f.nombre}: la prueba de hoy falló (${pr.paso})`);
  if (!pr) avisos.push(`${f.nombre}: no hay prueba de hoy`);
  if (f.mediaDia >= 3 && f.ayer === 0) avisos.push(`${f.nombre}: ayer no entró ningún lead (normalmente ${f.mediaDia.toFixed(0)} al día)`);
  if (f.mediaSem >= 5 && f.sem.total < f.mediaSem * 0.6) avisos.push(`${f.nombre}: ${f.sem.total} leads en 7 días, muy por debajo de su media (${f.mediaSem.toFixed(0)})`);
  if (p !== null && pm !== null && f.sem.total >= 10 && p < pm - 15) avisos.push(`${f.nombre}: solo ${p} % llega a cotización (en ${iniMesAnt.setLocale('es').toFormat('LLLL')} ${pm} %)`);
  tabla += `<tr><td ${tdl}><b>${f.nombre}</b></td><td ${td}>${f.sem.total}${delta(f.sem.total, f.mediaSem)}</td><td ${td}>${f.mediaSem ? f.mediaSem.toFixed(0) : '–'}${f.mesCompleto ? '' : '*'}</td><td ${td}>${f.ayer}</td><td ${td}><span style="color:${p !== null && pm !== null ? (p < pm - 10 ? '#cf222e' : p > pm + 10 ? '#1a7f37' : '#222') : '#222'}">${p === null ? '–' : p + ' %'}</span></td><td ${td}>${pm === null ? '–' : pm + ' %'}</td><td ${td}>${f.sem.perdidos}</td><td ${td}>${f.sem.sinIA}</td><td ${td}>${prTxt}</td></tr>`;
}
const T = filas.reduce((t, f) => ({ total: t.total + f.sem.total, media: t.media + f.mediaSem, ayer: t.ayer + f.ayer, av: t.av + f.sem.avance, mt: t.mt + f.mes.total, mav: t.mav + f.mes.avance, per: t.per + f.sem.perdidos, sin: t.sin + f.sem.sinIA }), { total: 0, media: 0, ayer: 0, av: 0, mt: 0, mav: 0, per: 0, sin: 0 });
tabla += `<tr><td ${tdl}><b>Total</b></td><td ${td}><b>${T.total}</b>${delta(T.total, T.media)}</td><td ${td}>${T.media.toFixed(0)}</td><td ${td}>${T.ayer}</td><td ${td}><b>${pct(T.av, T.total) ?? '–'} %</b></td><td ${td}>${pct(T.mav, T.mt) ?? '–'} %</td><td ${td}>${T.per}</td><td ${td}>${T.sin}</td><td ${td}></td></tr></table>`;

let tablaResc = `<h3 style="margin:22px 0 6px;font-size:16px">Rescates automáticos (ayer 8:00 → hoy 8:00)</h3><table style="border-collapse:collapse;width:100%;font-size:14px"><tr><th ${thl}>Agencia</th><th ${th}>Vueltas</th><th ${th}>Clientes rescatados</th><th ${th}>Ya los atendía el equipo</th><th ${th}>Envíos fallidos</th><th ${th}>¿Todo bien?</th></tr>`;
for (const f of filas) {
  const r = resc[f.ag] || { apiError: true };
  const okR = !r.apiError && r.vueltas >= esperadas && !r.errores && !r.fallidos;
  const det = r.apiError ? 'no se pudo leer' : [r.vueltas < esperadas ? `faltaron ${esperadas - r.vueltas} vueltas` : '', r.errores ? `${r.errores} vueltas con error` : '', r.fallidos ? `${r.fallidos} envíos fallaron` : ''].filter(Boolean).join(', ');
  if (!okR) avisos.push(`${f.nombre}: rescates – ${det}`);
  tablaResc += `<tr><td ${tdl}><b>${f.nombre}</b></td><td ${td}>${r.apiError ? '–' : `${r.vueltas} de ${esperadas}`}</td><td ${td}>${r.rescatados ?? '–'}</td><td ${td}>${r.omitidos ?? '–'}</td><td ${td}>${r.fallidos ?? '–'}</td><td ${td}>${okR ? '✅' : `<span style="color:#cf222e">⚠️ ${det}</span>`}</td></tr>`;
}
tablaResc += `</table><p style="font-size:12px;color:#666;margin:6px 0 0">Rescatados = clientes que escribieron y no tenían respuesta; se le pasaron a la IA para que contestara. "Ya los atendía el equipo" = se revisaron pero no se tocaron porque los lleva una vendedora.</p>`;
const fmt = (d) => new Date(d).toLocaleDateString('es-MX', { day: 'numeric', month: 'short', timeZone: 'America/Mexico_City' });
const estado = avisos.length ? `<div style="background:#fff8c5;border:1px solid #d4a72c;padding:10px 12px;border-radius:6px;margin:0 0 16px"><b>⚠️ Revisar:</b><br>${avisos.join('<br>')}</div>`
  : `<div style="background:#dafbe1;border:1px solid #4ac26b;padding:10px 12px;border-radius:6px;margin:0 0 16px"><b>✅ Todo funciona bien.</b> Las pruebas de hoy pasaron y el volumen de leads es normal.</div>`;
const html = `<div style="font-family:Arial,sans-serif;color:#222;max-width:820px">
<h2 style="margin:0 0 4px">Reporte diario – Rs Viajes</h2>
<p style="margin:0 0 14px;color:#555">Leads del ${fmt(ahora - 7 * DIA)} al ${fmt(ahora)} comparados con la media semanal de ${iniMesAnt.setLocale('es').toFormat('LLLL')}.</p>
${estado}${tabla}
<p style="font-size:12px;color:#666;margin:8px 0 0">% a cotización = leads que llegaron a datos completos, cotización o venta. Perdidos = Última oportunidad + Cliente perdido. Sin IA = WhatsApp que no viene de anuncio. Verde/rojo = más de 15 % arriba/abajo de la media.${filas.some(f => f.raros.length) ? ' Sin contar días con importaciones masivas: ' + filas.filter(f => f.raros.length).map(f => f.nombre + ' ' + f.raros.map(d => d.slice(8) + '/' + d.slice(5, 7)).join(', ')).join('; ') + '.' : ''}${filas.some(f => !f.mesCompleto) ? ' * Media con los días que hay datos: ' + filas.filter(f => !f.mesCompleto).map(f => f.nombre + ' ' + f.desdeTxt).join(', ') + '.' : ''}</p>${tablaResc}</div>`;
const asunto = avisos.length ? `⚠️ Rs Viajes hoy: revisar ${[...new Set(avisos.map(a => a.split(':')[0]))].join(', ')}` : `✅ Rs Viajes hoy: todo bien · ${T.total} leads en 7 días (media ${T.media.toFixed(0)})`;
return [{ json: { asunto, html } }];

// Ejecuciones de los rescates automáticos de cada agencia (para contar las vueltas y los rescates del último día)
const R = { independencia: 'v1IbX9iTc4RmSx8Q', centro: 'IyKHh3bSY3sdamxT', periodismo: 'OW3XE9c3w6xUmBIF', matriz: 'awNBTdlMxxZ4lW3l', hijar: 'nXnbDqxdgjIiJ5NG', saltillo: 'Zra1ZyyM1q9rIy5K' };
return Object.entries(R).map(([agencia, id]) => ({ json: { agencia, url: `http://localhost:5678/api/v1/executions?workflowId=${id}&limit=100&includeData=true` } }));
